/* ============================================================== 7 · results */

/* -------------------------------------------------------- Figure: the balance (Accumulator)
 *
 * Family: Accumulator — "this compounds". The balancing bias moves by a fixed step after every
 * training step, so balance is not set, it accumulates; the reader steps through training and
 * watches a lopsided router even out over hundreds of steps. One predict-before-reveal.
 *
 * Two sources, and the figure keeps them apart. The bars are the FIRST block's per-expert loads,
 * which only the log records, every `log_every` steps. The trace and the idle strip are the bundle's
 * figures over EVERY block at EVERY step. The caption says so; it is the easiest thing here to blur.
 */
function balanceFigure(M) {
  const cfg = M.config;
  const b = M.balance;
  const rows = M.layer0;
  const total = M.continuation.steps;
  const n = cfg.n_experts;

  const W = 480;
  const H = 416;
  const X0 = 84;
  const X1 = 472;
  const slot = (X1 - X0) / n;
  const barW = slot * 0.56;
  const A = { top: 30, base: 190 };
  const T = { top: 254, base: 314 };
  const D = { top: 356, base: 390 };
  const yLoad = (v) => A.base - v * (A.base - A.top);
  const xStep = (s) => X0 + ((s - 1) / (total - 1)) * (X1 - X0);
  const yViol = (v) => T.base - (v / b.ceiling) * (T.base - T.top);

  let at = 0;
  let revealed = false;
  let guess = null;

  const wrap = el('div', 'acc');
  wrap.setAttribute('role', 'group');
  wrap.setAttribute('aria-label', 'The router over training: loads, imbalance and idle experts');

  /* Predict before reveal — the idle strip stays veiled until the reader commits. The answer is in
   * the prose after the figure as well, so a reader who never guesses still gets it. */
  const ask = el('div', 'acc-ask');
  const askP = el('p', 'acc-q');
  askP.innerHTML = `<b>Guess first.</b> Of all ${int(M.params.experts_stored)} experts in the model,
    what is the most that sat <b>idle</b> — no tokens at all — in a single step?`;
  const guessIn = el('input');
  guessIn.type = 'range';
  guessIn.min = '0';
  guessIn.max = String(M.params.experts_stored);
  guessIn.step = '1';
  guessIn.value = '0';
  guessIn.id = 'acc-guess';
  guessIn.setAttribute('aria-label', 'Your guess: the most experts idle in one step');
  const guessOut = el('output', 'acc-gout', '0');
  guessOut.htmlFor = 'acc-guess';
  const revealBtn = el('button', 'acc-reveal', 'Reveal');
  revealBtn.type = 'button';
  const answer = el('p', 'acc-answer');
  const askRow = el('div', 'acc-askrow');
  askRow.append(guessIn, guessOut, revealBtn);
  ask.append(askP, askRow, answer);
  guessIn.addEventListener('input', () => {
    guessOut.textContent = guessIn.value;
  });
  revealBtn.addEventListener('click', () => {
    guess = Number(guessIn.value);
    revealed = true;
    show(at);
  });

  const node = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'chart accfig',
    role: 'img',
    'aria-label':
      'Per-expert loads in the first block at the chosen step, against an even share; below, the ' +
      'largest imbalance over every block at every step, and the steps that had idle experts.',
  });

  /* Panel A — the first block's loads. */
  node.append(svgText(X0, 16, 'fig-lab', 'first block only · share of tokens per expert'));
  for (const [v, label] of [
    [0, '0'],
    [b.even_share, `even ${b.even_share}`],
    [1, 'every token'],
  ]) {
    node.append(
      svg('line', { x1: X0, x2: X1, y1: yLoad(v), y2: yLoad(v), class: v === b.even_share ? 'acc-even' : 'gridline' }),
      svgText(X0 - 6, yLoad(v) + 4, 'ax end', label)
    );
  }
  const bars = [];
  const vals = [];
  for (let i = 0; i < n; i += 1) {
    const cx = X0 + slot * i + slot / 2;
    const r = svg('rect', { x: cx - barW / 2, y: A.base, width: barW, height: 0, rx: 3, class: 'acc-bar' });
    const v = svgText(cx, A.base - 4, 'acc-v mid', '');
    bars.push(r);
    vals.push(v);
    node.append(r, v, svgText(cx, A.base + 15, 'ax mid', `E${i + 1}`));
  }

  /* Panel B — the largest imbalance over every block, every step. */
  node.append(svgText(X0, T.top - 12, 'fig-lab', 'every block · largest imbalance at each step'));
  node.append(
    svg('line', { x1: X0, x2: X1, y1: T.base, y2: T.base, class: 'gridline' }),
    svg('line', { x1: X0, x2: X1, y1: T.top, y2: T.top, class: 'gridline' }),
    svgText(X0 - 6, T.base + 4, 'ax end', '0'),
    svgText(X0 - 6, T.top + 4, 'ax end', String(b.ceiling))
  );
  const d = b.violation.map((v, i) => `${i ? 'L' : 'M'}${xStep(i + 1).toFixed(1)},${yViol(v).toFixed(1)}`).join(' ');
  node.append(svg('path', { d, class: 'acc-trace' }));

  /* Panel C — idle experts, every block, every step; veiled until the reader guesses. */
  node.append(svgText(X0, D.top - 12, 'fig-lab', 'every block · experts idle at each step'));
  const strip = svg('g', { class: 'acc-idle' });
  strip.append(svg('line', { x1: X0, x2: X1, y1: D.base, y2: D.base, class: 'gridline' }));
  b.dead.forEach((count, i) => {
    if (!count) return;
    const x = xStep(i + 1);
    const h = (count / b.worst_dead) * (D.base - D.top);
    strip.append(svg('line', { x1: x, x2: x, y1: D.base, y2: D.base - h, class: count === b.worst_dead ? 'acc-tick worst' : 'acc-tick' }));
  });
  const veil = svgText((X0 + X1) / 2, D.base - 10, 'acc-veil mid', 'hidden until you guess, above');
  node.append(strip, veil);
  node.append(
    svgText(X0, H - 6, 'ax', 'step 1'),
    svgText(X1, H - 6, 'ax end', `step ${int(total)}`)
  );
  const cursor = svg('line', { x1: X0, x2: X0, y1: T.top - 6, y2: D.base + 4, class: 'acc-cursor' });
  const dot = svg('circle', { cx: X0, cy: T.base, r: 4, class: 'acc-dot' });
  node.append(cursor, dot);

  /* The scrubber. */
  const ctl = el('div', 'acc-ctl');
  const slider = el('input');
  slider.type = 'range';
  slider.min = '0';
  slider.max = String(rows.length - 1);
  slider.step = '1';
  slider.value = '0';
  slider.id = 'acc-step';
  slider.setAttribute('aria-label', 'Step through training');
  const where = el('output', 'acc-where');
  where.htmlFor = 'acc-step';
  ctl.append(slider, where);
  slider.addEventListener('input', () => show(Number(slider.value)));

  const read = el('div', 'acc-read');

  /* guard() — every row was checked against the bundle by the renderer, so the only refusal left
   * is an index outside the log. */
  const guard = (i) => (i >= 0 && i < rows.length ? null : { note: 'No logged step there.' });

  /* stateFor(i) — PURE. */
  const stateFor = (i) => {
    const row = rows[i];
    const busiest = row.loads.indexOf(Math.max(...row.loads));
    return {
      step: row.step,
      loads: row.loads,
      busiest,
      busiestLoad: row.loads[busiest],
      times: row.loads[busiest] / b.even_share,
      violation: b.violation[row.step - 1],
      idle: b.dead[row.step - 1],
      bound: row.step * cfg.bias_rate,
    };
  };

  /* show(i) — RENDER ONLY. */
  function show(i) {
    at = i;
    slider.value = String(i);
    const refused = guard(i);
    if (refused) {
      read.textContent = refused.note;
      return;
    }
    const st = stateFor(i);
    bars.forEach((r, e) => {
      r.setAttribute('y', yLoad(st.loads[e]).toFixed(1));
      r.setAttribute('height', (A.base - yLoad(st.loads[e])).toFixed(1));
      r.classList.toggle('top', e === st.busiest);
      vals[e].setAttribute('y', (yLoad(st.loads[e]) - 5).toFixed(1));
      vals[e].textContent = st.loads[e].toFixed(3);
    });
    const x = xStep(st.step);
    cursor.setAttribute('x1', x.toFixed(1));
    cursor.setAttribute('x2', x.toFixed(1));
    dot.setAttribute('cx', x.toFixed(1));
    dot.setAttribute('cy', yViol(st.violation).toFixed(1));
    where.textContent = `after step ${int(st.step)} of ${int(total)}`;
    wrap.classList.toggle('revealed', revealed);
    veil.style.display = revealed ? 'none' : '';
    read.innerHTML = `
      <p><span class="acc-k">first block</span> the busiest expert, <b>E${st.busiest + 1}</b>, was
        chosen by ${st.busiestLoad.toFixed(3)} of its tokens — ${st.times.toFixed(1)}× an even share.</p>
      <p><span class="acc-k">every block</span> largest imbalance <b>${st.violation.toFixed(3)}</b> ·
        idle experts <b>${revealed ? int(st.idle) : 'hidden until you guess'}</b></p>
      <p><span class="acc-k">the bias</span> after ${int(st.step)} steps of ${cfg.bias_rate}, no
        expert's bias can have moved more than ${st.bound.toFixed(3)} — a bound, since the run does
        not record the biases themselves.</p>`;
    answer.innerHTML = revealed
      ? `${guess === null ? '' : `You guessed <b>${int(guess)}</b>. `}The most was
         <b>${int(b.worst_dead)}</b>, after steps ${steps(b.worst_dead_steps)}, and none at all after
         step ${int(b.last_idle)}.`
      : '';
    revealBtn.disabled = revealed;
  }

  wrap.playAll = () => {
    revealed = true;
    show(rows.length - 1);
  };
  wrap.append(ask, scroller(node), ctl, read);
  show(0);
  const fig = figure(
    playable(wrap),
    `<b>Balance is not set, it accumulates: a bias step of ${cfg.bias_rate} per step takes hundreds of
     steps to undo a lopsided router.</b> The bars are the <b>first block only</b> — the one block
     whose per-expert loads the training log records, every ${cfg.log_every} steps and rounded as the
     log writes them. The imbalance trace and the idle strip are over <b>every block, at every
     step</b>, from the results file. So a bar chart that looks even can sit above a trace that is
     not: another block can be lopsided while the first one is fine. <b>What would refute the
     balancing:</b> idle experts that keep appearing to the end of the run; the strip says they
     stop after step ${int(b.last_idle)}.`
  );
  fig.id = 'fig-balance';
  return fig;
}

/* -------------------------------------------------------- Figure: validation, MoE against dense */

function validationFigure(M) {
  const cont = M.continuation;
  const cv = M.curves;
  const total = cont.steps;
  const W = 480;
  const H = 438;
  const X0 = 50;
  const X1 = 360;
  const xs = (s) => X0 + (s / total) * (X1 - X0);

  const node = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'chart valfig',
    role: 'img',
    'aria-label':
      'Validation loss of the converted model and the dense control over training; below, their ' +
      'training-loss difference on identical batches; below that, the learning rate both followed.',
  });

  /* Panel A — validation. */
  const A = { top: 30, base: 200 };
  const all = cont.val.flatMap((p) => [p.moe, p.dense]);
  const lo = Math.min(...all);
  const hi = Math.max(...all);
  const pad = (hi - lo) * 0.08;
  const ya = (v) => A.base - ((v - (lo - pad)) / (hi - lo + 2 * pad)) * (A.base - A.top);
  node.append(svgText(X0, 16, 'fig-lab', 'validation loss, measured on held-out text'));
  for (const v of [lo, (lo + hi) / 2, hi]) {
    node.append(
      svg('line', { x1: X0, x2: X1, y1: ya(v), y2: ya(v), class: 'gridline' }),
      svgText(X0 - 6, ya(v) + 4, 'ax end', v.toFixed(3))
    );
  }
  const line = (key) => cont.val.map((p, i) => `${i ? 'L' : 'M'}${xs(p.step).toFixed(1)},${ya(p[key]).toFixed(1)}`).join(' ');
  node.append(svg('path', { d: line('dense'), class: 'series dense' }), svg('path', { d: line('moe'), class: 'series moe' }));
  for (const p of cont.val) {
    node.append(
      svg('rect', { x: xs(p.step) - 3.5, y: ya(p.dense) - 3.5, width: 7, height: 7, class: 'mk dense' }),
      svg('circle', { cx: xs(p.step), cy: ya(p.moe), r: 4, class: 'mk moe' })
    );
  }
  const endM = cont.val.at(-1);
  /* End labels placed apart from each other by at least a line, whichever ends higher. */
  const yM = ya(endM.moe);
  const yD = ya(endM.dense);
  const sep = 13;
  const [lm, ld] = yM > yD ? [Math.max(yM, yD + sep), yD] : [yM, Math.max(yD, yM + sep)];
  node.append(
    svgText(X1 + 10, lm + 4, 'ser-lab moe', `converted ${endM.moe.toFixed(4)}`),
    svgText(X1 + 10, ld + 4, 'ser-lab dense', `dense ${endM.dense.toFixed(4)}`),
    svgText(xs(0) + 8, ya(cont.start) + 16, 'ax', `both start at ${cont.start.toFixed(4)}`)
  );

  /* Panel B — the paired difference on training batches. */
  const B = { top: 252, base: 330 };
  const span = Math.max(...cv.paired.map(Math.abs));
  const yb = (v) => (B.top + B.base) / 2 - (v / span) * ((B.base - B.top) / 2);
  node.append(svgText(X0, B.top - 14, 'fig-lab', `converted minus dense, training loss, ${M.config.log_every}-step means`));
  node.append(
    svg('rect', { x: X0, y: B.top, width: X1 - X0, height: (B.base - B.top) / 2, class: 'acc-behind' }),
    svg('line', { x1: X0, x2: X1, y1: yb(0), y2: yb(0), class: 'zero' }),
    svgText(X0 - 6, yb(0) + 4, 'ax end', '0'),
    svgText(X1 + 10, B.top + 12, 'ax', 'converted behind'),
    svgText(X1 + 10, B.base - 2, 'ax', 'converted ahead')
  );
  const pd = cv.paired.map((v, i) => `${i ? 'L' : 'M'}${xs(cv.step[i]).toFixed(1)},${yb(v).toFixed(1)}`).join(' ');
  node.append(svg('path', { d: pd, class: 'series paired' }));

  /* Panel C — the learning rate both arms followed, from the log. */
  const C = { top: 376, base: 410 };
  const peak = Math.max(...cv.lr.map((r) => r.lr));
  const yc = (v) => C.base - (v / peak) * (C.base - C.top);
  node.append(svgText(X0, C.top - 10, 'fig-lab', `learning rate, both models · peak ${cont.lr}`));
  const area =
    `M${xs(0).toFixed(1)},${C.base} ` +
    cv.lr.map((r) => `L${xs(r.step).toFixed(1)},${yc(r.lr).toFixed(1)}`).join(' ') +
    ` L${xs(total).toFixed(1)},${C.base} Z`;
  node.append(svg('path', { d: area, class: 'lr-area' }), svg('line', { x1: X0, x2: X1, y1: C.base, y2: C.base, class: 'gridline' }));
  node.append(svgText(X0, H - 6, 'ax', 'step 0'), svgText(X1, H - 6, 'ax end', `step ${int(total)}`));

  const rise = cont.both_rise
    ? `<b>Both models get worse before they get better, so the rise belongs to the schedule and not
       to the conversion</b> — the unconverted control climbs too, to ${cont.dense_peak.toFixed(4)}
       against the converted model's ${cont.moe_peak.toFixed(4)}, as the learning rate is raised
       again.`
    : `<b>The two models do not both rise first</b>, so any early rise is not the schedule's alone.`;
  const middle =
    cont.behind_steps.length && cont.ahead_from
      ? `The converted model then trails from step ${int(cont.behind_steps[0])} to
         ${int(cont.behind_steps.at(-1))} and is ahead at every measurement from step
         ${int(cont.ahead_from)}, ending ${signed(cont.end_gap)}.`
      : `The converted model ends ${signed(cont.end_gap)} against the control.`;
  const fig = figure(
    node,
    `${rise} ${middle} The middle panel tells the same story from the training batches, where both
     models read identical text, so the batch-to-batch noise cancels. <b>What would refute the
     gain:</b> a spread between seeds as large as the gap itself — which a single run cannot
     measure.`
  );
  fig.id = 'fig-validation';
  return fig;
}

/* -------------------------------------------------------- Figure: what a token pays (Budget)
 *
 * Family: Budget — "you cannot have everything". The model stores every expert; a token draws k of
 * them. The reader moves k and watches what a token pays climb towards what is stored. Only the
 * run's own k was trained and timed: every other k is arithmetic from the counted parameters, drawn
 * hatched, and has no speed at all rather than an invented one.
 */
function costFigure(M) {
  const p = M.params;
  const cfg = M.config;
  const cont = M.continuation;
  const n = cfg.n_experts;
  const chunk = p.per_expert * cfg.depth; // one expert in every block

  const W = 480;
  const H = 312;
  const X0 = 116;
  const X1 = 466;
  const px = (v) => (v / p.total) * (X1 - X0);
  const ROW = { stored: 40, used: 118, dense: 178 };
  const BAR = 30;

  let k = cfg.top_k;

  const wrap = el('div', 'budget');
  wrap.setAttribute('role', 'group');
  wrap.setAttribute('aria-label', 'Parameters stored, parameters a token uses, and speed');

  const node = svg('svg', {
    viewBox: `0 0 ${W} ${H}`,
    class: 'chart budfig',
    role: 'img',
    'aria-label':
      'Parameters the converted model stores, the parameters one token uses at the chosen number ' +
      'of experts, the dense model for comparison, and tokens a second where they were measured.',
  });
  const defs = svg('defs');
  const pat = svg('pattern', { id: 'bud-hatch', width: 6, height: 6, patternUnits: 'userSpaceOnUse', patternTransform: 'rotate(45)' });
  pat.append(svg('rect', { width: 6, height: 6, class: 'hatch-bg' }), svg('line', { x1: 0, y1: 0, x2: 0, y2: 6, class: 'hatch-line' }));
  defs.append(pat);
  node.append(defs);

  const label = (y, text) => svgText(X0 - 10, y + BAR / 2 + 4, 'bud-k end', text);
  node.append(label(ROW.stored, 'stored'), label(ROW.used, 'one token uses'), label(ROW.dense, 'the dense model'));

  /* Stored: shared, then every expert-slot across all blocks. Dividers make the slots countable. */
  const segs = (y, experts, cls) => {
    const g = svg('g');
    g.append(svg('rect', { x: X0, y, width: px(p.shared), height: BAR, class: 'seg shared' }));
    let x = X0 + px(p.shared) + px(p.router_per_layer * cfg.depth);
    for (let e = 0; e < experts; e += 1) {
      g.append(svg('rect', { x, y, width: px(chunk), height: BAR, class: `seg ${cls}` }));
      x += px(chunk);
    }
    return g;
  };
  node.append(segs(ROW.stored, n, 'expert'));
  node.append(svgText(X1, ROW.stored - 6, 'bud-v end', int(p.total)));
  const used = svg('g');
  node.append(used);
  const usedVal = svgText(X0, ROW.used + BAR / 2 + 4, 'bud-v', '');
  node.append(usedVal);
  const denseG = svg('g');
  denseG.append(
    svg('rect', { x: X0, y: ROW.dense, width: px(p.shared), height: BAR, class: 'seg shared' }),
    svg('rect', { x: X0 + px(p.shared), y: ROW.dense, width: px(chunk), height: BAR, class: 'seg dense' })
  );
  node.append(denseG, svgText(X0 + px(p.dense) + 8, ROW.dense + BAR / 2 + 4, 'bud-v', int(p.dense)));
  node.append(
    svgText(X0, ROW.stored + BAR + 14, 'ax', 'shared: attention, embeddings, norms'),
    svgText(X0, ROW.stored + BAR + 28, 'ax', `then one slot per expert, each across all ${cfg.depth} blocks`)
  );

  /* Speed, only where it was measured. */
  const SP = { y: 248, h: 14 };
  const fastest = Math.max(cont.tokens_per_second.dense, cont.tokens_per_second.moe);
  const sx = (v) => (v / fastest) * (X1 - X0) * 0.7;
  node.append(svgText(X0 - 10, SP.y - 2, 'bud-k end', 'tokens a second'));
  node.append(
    svg('rect', { x: X0, y: SP.y - SP.h, width: sx(cont.tokens_per_second.dense), height: SP.h, class: 'seg dense' }),
    svgText(X0 + sx(cont.tokens_per_second.dense) + 6, SP.y - 3, 'bud-v', `dense ${int(cont.tokens_per_second.dense)}`)
  );
  const speed = svg('g');
  node.append(speed);

  const ctl = el('div', 'acc-ctl');
  const slider = el('input');
  slider.type = 'range';
  slider.min = '1';
  slider.max = String(n);
  slider.step = '1';
  slider.value = String(k);
  slider.id = 'bud-k';
  slider.setAttribute('aria-label', 'Experts each token goes to');
  const kOut = el('output', 'acc-where');
  kOut.htmlFor = 'bud-k';
  ctl.append(slider, kOut);
  slider.addEventListener('input', () => show(Number(slider.value)));
  const read = el('p', 'dx-read');

  const guard = (kk) => (kk >= 1 && kk <= n ? null : { note: `k runs from one to ${n}.` });
  const stateFor = (kk) => ({ ...p.active_by_k[kk - 1] });

  function show(kk) {
    k = kk;
    slider.value = String(kk);
    const refused = guard(kk);
    if (refused) {
      read.textContent = refused.note;
      return;
    }
    const st = stateFor(kk);
    used.replaceChildren(segs(ROW.used, kk, st.run ? 'expert' : 'expert hatched'));
    usedVal.textContent = `${int(st.active)}${st.run ? '' : ' · arithmetic'}`;
    /* Beside the bar's end while there is room, above it once the bar fills the row. */
    const end = X0 + px(st.active) + 8;
    /* Estimated from the character count (11px mono is about 0.6em a glyph), because the first
     * call runs before the figure is in the document, where a measured text length is zero. */
    const fits = end + usedVal.textContent.length * 6.8 <= W - 4;
    usedVal.setAttribute('x', fits ? end : X1);
    usedVal.setAttribute('y', fits ? ROW.used + BAR / 2 + 4 : ROW.used - 6);
    usedVal.setAttribute('class', fits ? 'bud-v' : 'bud-v end');
    kOut.textContent = `k = ${kk}${st.run ? ' — the run’s own setting' : ''}`;
    speed.replaceChildren();
    const y2 = SP.y + 22;
    if (st.run) {
      speed.append(
        svg('rect', { x: X0, y: y2 - SP.h, width: sx(cont.tokens_per_second.moe), height: SP.h, class: 'seg expert' }),
        svgText(X0 + sx(cont.tokens_per_second.moe) + 6, y2 - 3, 'bud-v', `converted ${int(cont.tokens_per_second.moe)}`)
      );
    } else {
      speed.append(
        svg('line', { x1: X0, x2: X0 + 60, y1: y2 - 2, y2: y2 - SP.h, class: 'slash' }),
        svgText(X0 + 70, y2 - 3, 'ax', `converted: not run with k = ${kk}, so no speed`)
      );
    }
    wrap.dataset.k = String(kk);
    read.innerHTML = st.run
      ? `<b>At the run's own k, each token uses ${int(st.active)} of the ${int(p.total)} parameters
         stored</b> — ${pct(st.share, 0)} of them, and ${st.over_dense.toFixed(2)}× the dense model's
         ${int(p.dense)}. It ran at ${int(cont.tokens_per_second.moe)} tokens a second against the
         dense model's ${int(cont.tokens_per_second.dense)}.`
      : `At k = ${kk} each token would use ${int(st.active)} parameters — ${pct(st.share, 0)} of what
         is stored, ${st.over_dense.toFixed(2)}× the dense model. <b>That is arithmetic from the
         counted parameters, not a run</b>: drawn hatched, and with no speed, because none was
         measured.`;
  }

  wrap.playAll = () => show(cfg.top_k);
  wrap.append(scroller(node), ctl, read);
  show(k);
  const fig = figure(
    playable(wrap),
    `<b>What the model stores and what a token pays are different numbers, and the gap is the point
     of experts.</b> The stored bar is fixed at ${int(p.total)}; a token's share grows by one expert-slot
     per step of k and reaches all of it at k = ${n}, where every token pays for everything. At k = 1
     a token costs the dense model plus the routers. Only the run's k = ${cfg.top_k} was trained and
     timed; the rest is drawn hatched. The speed gap — ${cont.slowdown.toFixed(1)}× — is wider than
     the parameter gap of ${p.active_over_dense.toFixed(2)}×, and the rest belongs to a reference
     implementation that runs its experts one after another in a Python loop.`
  );
  fig.id = 'fig-cost';
  return fig;
}

function chapterResults(M) {
  const b = M.balance;
  const cont = M.continuation;
  const rt = M.router_trial;
  const cv = M.curves;
  const s = section(
    'results',
    'results',
    'What happened',
    'The router evens out, and the converted model pulls ahead late',
    [
      `Every figure below is read from the run's results file and its training log, and a test
       regenerates the page's data and fails if the tracked copy differs. First the router: does it
       use all its experts, or settle on a favourite few?`,
    ],
    { short: 'What happened', sub: 'balance, loss, and cost' }
  );

  s.append(balanceFigure(M));

  const bal = el('p', 'say');
  bal.innerHTML = `<b>The answer to the guess is ${spell(b.worst_dead)}</b>, after steps
    ${steps(b.worst_dead_steps)}, out of ${int(M.params.experts_stored)}. Steps with any idle expert
    numbered ${int(b.steps_with_idle)}, the last of them step ${int(b.last_idle)}. Early on the router
    is far from even — at ${int(b.steps_at_ceiling)} steps some block's busiest expert was chosen by
    every one of its tokens, the last time at step ${int(b.last_at_ceiling)} — and the busiest expert anywhere
    last reached twice its share at step ${int(b.last_twice_share)}. By the end the largest
    imbalance is ${b.end_violation.toFixed(3)}. In the first block, the one the log records, no
    expert's load ever reached zero at a logged step: the smallest was ${M.layer0_min_load}.`;
  s.append(bal);

  s.append(validationFigure(M));

  const val = el('p', 'say');
  val.innerHTML = `<b>The converted model ends ${signed(cont.end_gap)} against the dense control</b>,
    at ${cont.moe_end.toFixed(4)} to ${cont.dense_end.toFixed(4)}, having trailed by as much as
    ${cont.most_behind.toFixed(4)} at step ${int(cont.most_behind_step)}. On the training batches the
    last ${M.config.log_every}-step mean of the difference is ${signed(cv.paired_end)}. Whether the
    lopsided routing early on is why it trails in the middle, one run cannot say.`;
  s.append(val);

  s.append(
    table(
      ['router scoring', `validation loss after ${int(rt.tokens)} tokens`],
      Object.entries(rt.final_val).map(([name, v]) => ({
        cells: [name === rt.choice ? `<b>${name}</b> — kept` : name, v.toFixed(4)],
        __mark: name === rt.choice ? 'good' : undefined,
      }))
    )
  );
  const router = el('p', 'say small');
  router.innerHTML = `The router was chosen on a short trial before the main run, by
    ${rt.margin.toFixed(4)}, measured on the half of the validation text kept for choosing. One run each and no second seed, so this decides which router this run
    uses, not which is better.`;
  s.append(router);

  s.append(costFigure(M));
}

/* ============================================================== 8 · negatives */

function negativeRows(M) {
  const rt = M.router_trial;
  const cont = M.continuation;
  return [
    {
      cells: [
        'The router chosen on the same validation text the results are reported on',
        'Could the choice flatter the converted model?',
        `Yes — it is the only model the choice applies to. Choosing and reporting now use separate
         halves of the validation text; apart from the router trial's own two numbers, every
         validation figure on this page comes from the half the choice never saw.`,
      ],
      __mark: 'bad',
    },
    {
      cells: [
        'A crash on the first run on the GPU',
        'How was it found, and what stops it coming back?',
        `On the device, not by the tests. The balancing bias and load counters were created on the
         CPU while the experts moved to the GPU, so routing added a CPU number to GPU scores. A test
         now holds them to the experts' device, and was watched failing against the old code.`,
      ],
      __mark: 'bad',
    },
    {
      cells: [
        'Results text that announced "the conversion changes nothing" as fixed wording',
        'Would it still say so if the conversion broke?',
        `It would have. The verdicts are computed now, and a test renders them both ways — the same
         reason this page reads every figure from the results file rather than typing it.`,
      ],
      __mark: 'bad',
    },
    {
      cells: [
        `Softmax kept over sigmoid scoring`,
        'By how much?',
        `${rt.margin.toFixed(4)} in validation loss, on one short run of ${int(rt.tokens)} tokens each.
         It is a choice of which router to use, not a ranking of the two.`,
      ],
      __mark: 'warn',
    },
    {
      cells: [
        'The converted model behind the dense control mid-run',
        'Is the final lead safe?',
        `It trailed at ${spell(cont.behind_steps.length)} validation checks, by up to
         ${cont.most_behind.toFixed(4)}, and led from step ${int(cont.ahead_from)}. With one run each
         and no spread between seeds, the final ${signed(cont.end_gap)} is these two runs, not the
         design.`,
      ],
      __mark: 'warn',
    },
  ];
}

function chapterNegatives(M) {
  const rows = negativeRows(M);
  const s = section(
    'negatives',
    'negatives',
    'What went wrong, and what did not hold',
    `${Spell(rows.length)} things that went wrong, or held only weakly`,
    [
      `The first three were mistakes in this exercise's own work, found and fixed before the run on
       this page. The last two are results that are weaker than they look, and are reported that
       way.`,
    ],
    { short: 'What went wrong', sub: 'mistakes found, and weak results' }
  );

  s.append(table(['as it was', 'the question asked of it', 'what it is now'], rows, 'grid prose'));
}

/* ============================================================== 9 · conclusion */

function chapterConclusion(M) {
  const cont = M.continuation;
  const b = M.balance;
  const s = section(
    'conclusion',
    'conclusion',
    'The verdict',
    'An exact start, a balanced router, and a lead too small to rank',
    [
      `Copying a trained layer into experts and rescaling the kept weights to add up to one converts a
       model without changing it — measured here, not assumed. From that start the router piled
       tokens onto a few experts for a few hundred steps and then evened out, with no expert idle
       after step ${int(b.last_idle)}.`,
      `The converted model ends ${signed(cont.end_gap)} against an unconverted model given the same
       training, after trailing it in the middle. That is a result about these two runs. Whether it
       is a result about the design needs more than one seed.`,
    ],
    { short: 'The verdict', sub: 'what the run establishes' }
  );

  const box = el('div', 'takeaway');
  box.innerHTML = `<b>The part that transfers.</b> Before comparing a converted model with anything,
    check that it starts where the original stopped — the loss before and after, to the last digit.
    Then give the original the same further training, or more parameters will look like a better
    design when they are only more training.`;
  s.append(box);
}

/* ============================================================== 10 · limits */

function chapterLimits(M) {
  const cont = M.continuation;
  const cfg = M.config;
  const items = [
    `<b>One seed, one run each.</b> The gap between the converted model and the control has no spread
     beside it, so its size cannot be ranked against noise.`,
    `<b>${int(cont.tokens)} tokens is a short continuation.</b> The experts start identical and drift
     apart only as routing tells them apart; a longer run could move the comparison either way.`,
    `<b>The router trial is a choice, not a study</b> — one short run per scoring rule.`,
    `<b>The speed is a reference implementation's.</b> Experts run one after another in a Python loop,
     so the ${int(cont.tokens_per_second.moe)} tokens a second says nothing about an optimised kernel.`,
    `<b>The text is the corpus the dense model already trained on</b>, drawn as new random windows.
     The continued model has read ${M.corpus.longest_run_epochs.toFixed(2)} epochs of it in total, so
     some windows overlap text it has seen; both models are affected alike.`,
    `<b>The per-expert loads are the first block's only</b>, every ${cfg.log_every} steps, because that
     is all the training log records. The imbalance and idle counts cover every block at every step.`,
  ];
  const s = section(
    'limits',
    'limits',
    'In the open',
    'What this page cannot tell you',
    [
      `In the open text rather than behind a disclosure, because a limitation a reader has to expand
       is a limitation the page is hiding.`,
    ],
    { short: 'The limits', sub: 'what one run cannot settle' }
  );
  s.classList.add('notice');

  const ul = el('ul', 'limitlist');
  for (const item of items) {
    const li = el('li');
    li.innerHTML = item;
    ul.append(li);
  }
  s.append(ul);
}

